deep.apiShape:
非 HTTP API，是可抄的内部调用面（Obsidian 1.x 运行时，公开 d.ts + 私有成员经插件逆向）：

```
// 源注册（公开）
workspace.registerHoverLinkSource(id: string, info: {display: string, defaultMod: boolean})

// 悬停事件（私有 trigger，payload 形状来自 zotlit/hover-editor 实码）
workspace.trigger("hover-link", {
  event: MouseEvent,        // 原始鼠标事件（读 Mod/坐标用）
  source: string,           // 注册的源 id
  hoverParent: HoverParent, // {hoverPopover: HoverPopover|null}，挂靠/复用容器
  targetEl: HTMLElement,    // 被悬停的链接元素，定位与 keepalive 锚
  linktext: string,         // 待解析目标（我们的 citekey/named-dest）
  sourcePath: string,       // 发出方上下文（解析相对路径用）
})

// popover（公开骨架 + 私有成员）
class HoverPopover extends Component {
  hoverEl: HTMLElement; state: PopoverState; // Showing|Shown|Hiding|Hidden
  constructor(parent: HoverParent, targetEl: HTMLElement|null, waitTime=300, staticPos?)
  position(pos?), hide(), show(), shouldShow(): boolean
}
// 历史（私有，pane-relief 逆向确认）
leaf.history: {backHistory: HistoryState[], forwardHistory: HistoryState[],
               go(offset): Promise<void>, deserialize({backHistory,forwardHistory})}
HistoryState = {title: string, icon: string, state: ViewState, eState: EphemeralState}
leaf.setViewState(viewState /* +popstate:true 表示回放 */, eState): Promise<ViewStateResult{history:boolean}>
leaf.setEphemeralState({focus?, subpath?, line?, startLoc?, endLoc?, scroll?})
leaf.trigger("history-change")  // 栈变动事件

// 解析（公开）
parseLinktext(s): {path, subpath}
metadataCache.getFirstLinkpathDest(linkpath, sourcePath): TFile|null
resolveSubpath(cache, subpath): HeadingSubpathResult|BlockSubpathResult|FootnoteSubpathResult|null

// 分派与渲染（公开）
Keymap.isModEvent(e): 'tab'|'split'|'window'|false
Keymap.isModifier(e, 'Mod'): boolean
MarkdownRenderer.render(app, markdown, el, sourcePath, component): Promise<void>
leaf.openFile(file, {state?, eState?, active?, group?}): Promise<void>
```
